_np = [['Write your community purpose in one sentence of fewer than 20 words, and name the first 20 people you could invite, because a community with a clear aim and 20 real members is ready to open.', 'Check that people need the community by asking five possible members what they would use it for; if fewer than three give a concrete answer, narrow the purpose.'], ["Write rules as five short sentences that say what to do, such as 'be kind, stay on topic, no selling', and pin them where every new member sees them on joining.", 'Set a three-step response ladder: a friendly reminder, a temporary pause of 24 hours, then removal, and write down each action so decisions are fair and repeatable.'], ["Choose a space type by matching it to your members' habits: a group chat for quick talk, a forum for lasting answers, a video room for events; avoid using more than two at the start.", 'Prepare a welcome post, a pinned rules post and three starter questions before opening, so the first visitor sees a space that already feels lived in.'], ['Plan a weekly rhythm: one question on Monday, one useful resource on Wednesday and one member story on Friday, which gives three posts per week and takes under two hours.', 'Keep a bank of ten ideas ahead of time and reuse the best performing post format; if a type gets twice as many replies as others, do more of it.'], ['Invite members personally with a short message explaining the purpose, and aim to bring in 5 to 10 people per week instead of buying a sudden large crowd.', 'Ask each active member to invite one friend who would truly benefit, and thank people publicly, because growth by trust brings members who stay.'], ['Welcome every new member within 24 hours by name, point them to one easy first action such as introducing themselves, and reply to their first post within a day.', 'Moderate with a checklist: read the report, check the rule, act on the ladder, record the decision, and message the member kindly, which takes under five minutes per case.'], ['Track four numbers weekly: new members, active members who posted or replied, replies per post, and members who return after 30 days; focus on active share, not total size.', 'Aim for 20 percent of members active in a month; if you are at 10 percent, plan one change, such as a weekly question, and re-check after four weeks.'], ['Hold a monthly review with members: ask what they like, what they would change and who might help run events, and note the answers in a shared list.', 'Share the work by inviting two volunteers to help with welcoming or events, giving them a clear task list so the community does not rest on one person.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]
C['intro_add'] = ["You will state a community's purpose in one short sentence and test it with five possible members before investing time in building.", 'You will write five short rules and a three-step response ladder, so moderation is fair, visible and the same for everyone.', "You will choose the one or two spaces that match members' habits and prepare a welcome kit, so the first visitor finds a living place.", 'You will plan a weekly posting rhythm backed by a bank of ten ideas, keeping the community active without exhausting its organiser.', 'You will invite members personally and ask them to bring one friend, building steady growth rooted in trust rather than bought numbers.', 'You will welcome newcomers within a day and handle reports with a five-minute checklist, setting a friendly tone from the first reply.', 'You will track active share, replies per post and thirty-day return, and read them to see whether people truly value the space.', 'You will hold a monthly member review and recruit two volunteers, so the community improves and no longer depends on one person.']
